    TwistSquash::SquashKeyA(MIMOSA_KEY_A_G_IceLaneA, MIMOSA_KEY_A_G_IceLaneB, MIMOSA_KEY_A_G_IceLaneC, MIMOSA_KEY_A_G_IceLaneD, &(pWorkSpace->mKeyBoxA[6U][0]));

    // Key flow — A / H

    //
