    TwistSquash::SquashKeyA(MIMOSA_KEY_B_E_IceLaneA, MIMOSA_KEY_B_E_IceLaneB, MIMOSA_KEY_B_E_IceLaneC, MIMOSA_KEY_B_E_IceLaneD, &(pWorkSpace->mKeyBoxB[4U][0]));

    // Key flow — B / F

    //
    // src: [$earth, $crystal]
