    TwistSquash::SquashKeyA(MIMOSA_KEY_B_F_IceLaneA, MIMOSA_KEY_B_F_IceLaneB, MIMOSA_KEY_B_F_IceLaneC, MIMOSA_KEY_B_F_IceLaneD, &(pWorkSpace->mKeyBoxB[5U][0]));

    // Key flow — B / G

