    TwistSquash::SquashKeyA(MIMOSA_KEY_B_G_IceLaneA, MIMOSA_KEY_B_G_IceLaneB, MIMOSA_KEY_B_G_IceLaneC, MIMOSA_KEY_B_G_IceLaneD, &(pWorkSpace->mKeyBoxB[6U][0]));

